DELETE FROM `cooldowns`
WHERE `SkillID` IN (11121000, 11121001, 11121002, 11121003, 11121004);

DELETE FROM `keymap`
WHERE `action` IN (11121000, 11121001, 11121002, 11121003, 11121004);

DELETE FROM `skillmacros`
WHERE `skill1` IN (11121000, 11121001, 11121002, 11121003, 11121004)
   OR `skill2` IN (11121000, 11121001, 11121002, 11121003, 11121004)
   OR `skill3` IN (11121000, 11121001, 11121002, 11121003, 11121004);

DELETE FROM `skills`
WHERE `skillid` IN (11121000, 11121001, 11121002, 11121003, 11121004);
